// Pedido do painel (criar uma mensagem ou atualizar a lista) ou rodada agendada (atualizar a lista).
const doPainel = $('Webhook: painel').isExecuted;
const b = doPainel ? ($('Webhook: painel').first().json.body ?? {}) : {};
const waba = String($input.first().json.waba_id ?? '').trim();
const linha = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();
const acao = doPainel ? linha(b.acao).toLowerCase() : 'sincronizar';
const base = { origem: doPainel ? 'painel' : 'agenda', acao, waba };
const erros = [];
if (!/^\d{5,}$/.test(waba)) erros.push('O ID da conta do WhatsApp (config_disparos.waba_id) não está preenchido. Avise o suporte.');
if (!['criar', 'sincronizar'].includes(acao)) erros.push('Ação inválida: ' + (acao || 'vazia') + '.');
if (acao !== 'criar' || erros.length) return [{ json: { ...base, ok: !erros.length, erros } }];

// Mensagem nova. O painel já valida; aqui a conferência se repete, porque a Meta recusa sem explicar bem.
const texto = (s) => String(s ?? '').replace(/\r/g, '').replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
const nome = linha(b.nome);
const categoria = linha(b.categoria).toUpperCase();
const idioma = linha(b.idioma) || 'pt_BR';
const cabecalho = linha(b.cabecalho);
const corpo = texto(b.corpo);
const rodape = linha(b.rodape);
const variaveis = (Array.isArray(b.variaveis) ? b.variaveis : []).map((v, i) => ({ n: i + 1, campo: linha(v?.campo).toLowerCase(), exemplo: linha(v?.exemplo) }));
const botoes = (Array.isArray(b.botoes) ? b.botoes : []).map((x) => ({ tipo: x?.tipo === 'link' ? 'link' : 'resposta', texto: linha(x?.texto), url: linha(x?.url) }));
const respostas = botoes.filter((x) => x.tipo === 'resposta').map(({ tipo, texto }) => ({ tipo, texto }));
const links = botoes.filter((x) => x.tipo === 'link');

if (!/^[a-z0-9_]{1,512}$/.test(nome)) erros.push('Nome inválido: use só letras minúsculas, números e _.');
if (!['MARKETING', 'UTILITY'].includes(categoria)) erros.push('Categoria inválida: use Marketing ou Utilidade.');
if (!/^[a-z]{2,3}(_[A-Z]{2})?$/.test(idioma)) erros.push('Idioma inválido.');
if (cabecalho.length > 60) erros.push('O título em destaque pode ter até 60 caracteres.');
if (/[{}]/.test(cabecalho)) erros.push('O título em destaque não pode ter campos variáveis.');
if (!corpo) erros.push('Escreva o texto da mensagem.');
if (corpo.length > 1024) erros.push('O texto pode ter até 1.024 caracteres.');
if (rodape.length > 60) erros.push('O rodapé pode ter até 60 caracteres.');
if (/[{}]/.test(rodape)) erros.push('O rodapé não pode ter campos variáveis.');
// Campos do corpo: {{1}}, {{2}}... na ordem em que aparecem pela primeira vez, um exemplo para cada.
const ordem = [...new Set([...corpo.matchAll(/\{\{(\d+)\}\}/g)].map((m) => Number(m[1])))];
if (/[{}]/.test(corpo.replace(/\{\{\d+\}\}/g, ''))) erros.push('Há um campo variável mal escrito no texto.');
if (ordem.some((n, i) => n !== i + 1)) erros.push('Os campos do texto precisam ser {{1}}, {{2}}... na ordem em que aparecem.');
if (variaveis.length !== ordem.length || variaveis.some((v) => !v.exemplo)) erros.push('Informe um exemplo para cada campo do texto.');
if (variaveis.some((v) => v.exemplo.length > 200)) erros.push('Cada exemplo pode ter até 200 caracteres.');
if (/^\{\{\d+\}\}/.test(corpo) || /\{\{\d+\}\}$/.test(corpo)) erros.push('O texto não pode começar nem terminar com um campo variável.');
if (respostas.length > 3) erros.push('Use no máximo 3 respostas rápidas.');
if (links.length > 2) erros.push('Use no máximo 2 botões de link.');
if (botoes.some((x) => !x.texto || x.texto.length > 25)) erros.push('O texto de cada botão precisa ter de 1 a 25 caracteres.');
if (links.some((x) => !/^https:\/\/[^\s{}]+\.[^\s{}]+$/i.test(x.url) || x.url.length > 2000)) erros.push('O endereço de cada botão de link precisa começar com https:// e não pode ter espaços.');
const titulo = linha(b.titulo).slice(0, 120);
if (erros.length) return [{ json: { ...base, ok: false, erros: [...new Set(erros)] } }];

const componentes = [];
if (cabecalho) componentes.push({ type: 'HEADER', format: 'TEXT', text: cabecalho });
componentes.push(variaveis.length ? { type: 'BODY', text: corpo, example: { body_text: [variaveis.map((v) => v.exemplo)] } } : { type: 'BODY', text: corpo });
if (rodape) componentes.push({ type: 'FOOTER', text: rodape });
// A Meta exige os botões em grupos: as respostas rápidas juntas, depois os links.
const emOrdem = [...respostas, ...links];
if (emOrdem.length) {
  componentes.push({ type: 'BUTTONS', buttons: emOrdem.map((x) => (x.tipo === 'link' ? { type: 'URL', text: x.texto, url: x.url } : { type: 'QUICK_REPLY', text: x.texto })) });
}
return [{ json: {
  ...base,
  ok: true,
  erros: [],
  corpo_meta: { name: nome, language: idioma, category: categoria, components: componentes },
  registro: { nome, idioma, categoria, titulo: titulo || null, cabecalho: cabecalho || null, corpo, rodape: rodape || null, botoes: emOrdem, variaveis, criado_por: linha(b.criado_por) || null },
} }];

// Resposta da Meta ao pedido de aprovação: o ID e a situação da mensagem, ou o motivo da recusa.
const pedido = $('Montar pedido').first().json;
const r = $input.first().json;
const status = Number(r.statusCode || 0);
let corpo = r.body;
if (typeof corpo === 'string') { try { corpo = JSON.parse(corpo); } catch (e) { corpo = {}; } }
corpo = corpo || {};
if (status >= 200 && status < 300 && corpo.id) {
  return [{ json: { ok: true, modelo: {
    ...pedido.registro,
    id: String(corpo.id),
    status: String(corpo.status || 'PENDING').toUpperCase(),
    // A Meta pode mudar a categoria pedida (por exemplo, de Utilidade para Marketing).
    categoria: String(corpo.category || pedido.registro.categoria).toUpperCase(),
  } } }];
}
const e = corpo.error || {};
const original = [e.error_user_title, e.error_user_msg || e.message].filter(Boolean).join(': ') || 'erro ' + (status || 'de rede') + ' sem detalhe';
const codigo = Number(e.code || 0);
const TRADUCOES = [
  [() => codigo === 190, 'A chave de acesso da Meta venceu ou foi trocada. Avise o suporte.'],
  [() => codigo === 10 || codigo === 200 || /permission/i.test(original), 'A chave da Meta não tem permissão para criar mensagens (whatsapp_business_management). Avise o suporte.'],
  [() => /being deleted/i.test(original), 'Uma mensagem com esse nome foi apagada há pouco na Meta, e o nome só volta a valer depois de 4 semanas. Mude o nome.'],
  [() => /already exists/i.test(original), 'Já existe uma mensagem com esse nome e idioma na Meta. Mude o nome.'],
  [() => /(start|beginning) or (the )?end/i.test(original), 'O texto não pode começar nem terminar com um campo variável.'],
  [() => /too many (variables|parameters)|parameters? to (the )?(message )?length/i.test(original), 'Há campos variáveis demais para o tamanho do texto. Escreva mais texto fixo ou use menos campos.'],
  [() => /per hour|rate limit/i.test(original) || codigo === 4 || codigo === 80008, 'A Meta limita quantas mensagens podem ser criadas por hora. Tente de novo mais tarde.'],
];
const traducao = TRADUCOES.find(([teste]) => teste());
const erro = traducao ? traducao[1] + ' (Meta: ' + original + ')' : 'A Meta recusou a mensagem: ' + original;
return [{ json: { ok: false, http_status: status >= 500 || !status ? 502 : 422, erro } }];

// Resposta ao painel. Na rodada agendada não há a quem responder: um erro vira falha da execução (e alerta).
const pedido = $('Montar pedido').first().json;
let status;
let resposta;
if (!pedido.ok) {
  status = 400;
  resposta = { ok: false, mensagem: pedido.erros.join(' '), erros: pedido.erros };
} else if (pedido.acao === 'criar') {
  const c = $('Ler resposta da Meta').first().json;
  if (!c.ok) {
    status = c.http_status || 422;
    resposta = { ok: false, mensagem: c.erro, erros: [c.erro] };
  } else {
    const m = c.modelo;
    const CATEGORIAS = { MARKETING: 'Marketing', UTILITY: 'Utilidade', AUTHENTICATION: 'Autenticação' };
    const partes = [];
    if (m.status === 'APPROVED') partes.push('A Meta já aprovou a mensagem. Ela pode ser usada em Nova campanha.');
    else if (m.status === 'REJECTED') partes.push('A Meta recusou a mensagem logo no envio. Veja o motivo na tela Mensagens, corrija e envie de novo com outro nome.');
    else partes.push('Mensagem enviada para aprovação da Meta. A análise costuma levar de alguns minutos a 24 horas, e a situação aparece na tela Mensagens.');
    if (m.categoria !== pedido.registro.categoria) partes.push('A Meta classificou a mensagem como ' + (CATEGORIAS[m.categoria] || m.categoria) + '.');
    status = 200;
    resposta = { ok: true, mensagem: partes.join(' '), modelo: { id: m.id, nome: m.nome, status: m.status, categoria: m.categoria } };
  }
} else {
  const l = $('Juntar modelos').first().json;
  if (!l.ok) {
    status = 502;
    resposta = { ok: false, mensagem: l.erro, erros: [l.erro] };
  } else {
    status = 200;
    resposta = {
      ok: true,
      mensagem: 'Lista atualizada: ' + l.total + ' mensagem(ns) na Meta, ' + l.aprovados + ' aprovada(s), ' + l.em_analise + ' em análise e ' + l.recusados + ' recusada(s).',
      total: l.total, aprovados: l.aprovados, em_analise: l.em_analise, recusados: l.recusados,
    };
  }
}
if (pedido.origem === 'agenda') {
  if (!resposta.ok) throw new Error('Mensagens da Meta: ' + resposta.mensagem);
  return [];
}
return [{ json: { http_status: status, resposta } }];

// Junta as páginas da lista da Meta e diz, para cada mensagem, se o enviador consegue usá-la.
const paginas = $input.all().map((i) => i.json);
const problema = paginas.find((p) => Number(p.statusCode || 200) >= 300 || p.body?.error || p.error);
if (problema) {
  const e = problema.body?.error || {};
  const detalhe = [e.error_user_title, e.error_user_msg || e.message].filter(Boolean).join(': ') || (typeof problema.error === 'string' ? problema.error : problema.error?.message) || 'erro ' + (problema.statusCode || 'de rede');
  return [{ json: { ok: false, erro: 'Não foi possível ler as mensagens na Meta: ' + detalhe } }];
}

function converter(t) {
  const comps = Array.isArray(t.components) ? t.components : [];
  const achar = (tipo) => comps.find((c) => String(c.type).toUpperCase() === tipo);
  const problemas = [];
  const header = achar('HEADER');
  let cabecalho = null;
  if (header) {
    if (String(header.format || 'TEXT').toUpperCase() !== 'TEXT') problemas.push('título com imagem, vídeo ou documento');
    else {
      cabecalho = String(header.text || '');
      if (/\{\{/.test(cabecalho)) problemas.push('campo variável no título');
    }
  }
  const corpo = String(achar('BODY')?.text || '');
  const footer = achar('FOOTER');
  const botoes = (achar('BUTTONS')?.buttons || []).map((x) => {
    const tipo = String(x.type || '').toUpperCase();
    if (tipo === 'QUICK_REPLY') return { tipo: 'resposta', texto: String(x.text || '') };
    if (tipo === 'URL') {
      if (/\{\{/.test(String(x.url || ''))) problemas.push('link com parte variável');
      return { tipo: 'link', texto: String(x.text || ''), url: String(x.url || '') };
    }
    if (tipo === 'PHONE_NUMBER') return { tipo: 'telefone', texto: String(x.text || ''), telefone: String(x.phone_number || '') };
    problemas.push('botão do tipo ' + tipo.toLowerCase());
    return { tipo: tipo.toLowerCase(), texto: String(x.text || '') };
  });
  const outros = comps.filter((c) => !['HEADER', 'BODY', 'FOOTER', 'BUTTONS'].includes(String(c.type).toUpperCase()));
  if (outros.length) problemas.push('parte do tipo ' + outros.map((c) => String(c.type).toLowerCase()).join(', '));
  if (String(t.parameter_format || '').toUpperCase() === 'NAMED') problemas.push('campos variáveis com nome');
  const categoria = String(t.category || '').toUpperCase();
  if (categoria === 'AUTHENTICATION') problemas.push('mensagem de autenticação');
  const numeros = [...corpo.matchAll(/\{\{\s*(\d+)\s*\}\}/g)].map((m) => Number(m[1]));
  const motivo = String(t.rejected_reason || '').toUpperCase();
  return {
    id: String(t.id),
    nome: String(t.name || ''),
    idioma: String(t.language || ''),
    categoria,
    status: String(t.status || '').toUpperCase(),
    motivo: motivo && motivo !== 'NONE' ? motivo : null,
    cabecalho,
    corpo,
    rodape: footer ? String(footer.text || '') : null,
    botoes,
    n_variaveis: numeros.length ? Math.max(...numeros) : 0,
    suportado: problemas.length === 0,
    observacao: problemas.length ? 'Não dá para usar em campanha: ' + [...new Set(problemas)].join(', ') + '.' : null,
  };
}

const modelos = paginas.flatMap((p) => p.body?.data ?? p.data ?? []).filter((t) => t && t.id).map(converter);
const conta = (s) => modelos.filter((m) => s.includes(m.status)).length;
return [{ json: {
  ok: true,
  total: modelos.length,
  aprovados: conta(['APPROVED']),
  em_analise: conta(['PENDING', 'IN_APPEAL']),
  recusados: conta(['REJECTED']),
  modelos: JSON.stringify(modelos),
} }];
